let response = $input.first().json ?? {};

if (typeof response === 'string') {
  try {
    response = JSON.parse(response);
  } catch (e) {
    throw new Error('USGS returned invalid JSON string.');
  }
}

const features = Array.isArray(response.features) ? response.features : [];
const STATE_KEY = 'njQuakeStateV1';
const USGS_MAP_URL = 'https://earthquake.usgs.gov/earthquakes/map/';

const formatEastern = (timestamp) => {
  return new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  }).format(new Date(timestamp));
};

const currentEvents = {};
for (const feat of features) {
  const id = String(feat.id);
  const props = feat.properties || {};
  const geom = feat.geometry || {};
  const coords = Array.isArray(geom.coordinates) ? geom.coordinates : [0, 0, 0];

  currentEvents[id] = {
    id,
    mag: Number(props.mag ?? 0),
    place: String(props.place ?? 'Unknown location').trim(),
    time: props.time ?? Date.now(),
    url: String(props.url ?? USGS_MAP_URL),
    type: String(props.type ?? 'earthquake').toUpperCase(),
    felt: props.felt ?? null,
    cdi: props.cdi ?? null,
    depthKm: coords[2] ?? null,
    longitude: coords[0] ?? null,
    latitude: coords[1] ?? null
  };
}

const staticData = $getWorkflowStaticData('global');
const previousSeen = staticData[STATE_KEY] ?? [];

// Determine which events are newly discovered
const newEvents = [];
for (const [id, ev] of Object.entries(currentEvents)) {
  if (!previousSeen.includes(id)) {
    newEvents.push(ev);
  }
}

// Update state with active 7-day event IDs
staticData[STATE_KEY] = Object.keys(currentEvents);

// If nothing new, stop execution
if (newEvents.length === 0) {
  return [{ json: { shouldSend: false, reason: 'No new seismic events.', ntfyPayload: null } }];
}

// Sort newest events first
newEvents.sort((a, b) => b.time - a.time);

const getMagIcon = (mag) => {
  if (mag >= 3.0) return '🟥';
  if (mag >= 1.5) return '🟨';
  return '🟩';
};

const lines = [];
lines.push('**SEISMIC ACTIVITY DETECTED**');
lines.push('');

for (const ev of newEvents) {
  const icon = getMagIcon(ev.mag);
  lines.push(`${icon} **M ${ev.mag.toFixed(1)}** — *${ev.place}*`);
  lines.push(`> Event Type: ${ev.type}`);
  lines.push(`> Time: ${formatEastern(ev.time)}`);
  if (ev.depthKm !== null) lines.push(`> Depth: ${ev.depthKm} km`);
  if (ev.felt !== null) lines.push(`> Felt Reports: ${ev.felt}`);
  lines.push(`> [USGS Event Page](${ev.url})`);
  lines.push('');
}

lines.push(`Updated ${new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: '2-digit', minute: '2-digit', hour12: true }).format(new Date())}`);

const highestMag = Math.max(...newEvents.map(e => e.mag));
let title = `Earthquake Alert: M ${highestMag.toFixed(1)} in Region`;
if (newEvents.length > 1) {
  title = `${newEvents.length} New Seismic Events (Max M ${highestMag.toFixed(1)})`;
}

let priority = 3;
if (highestMag >= 3.0) {
  priority = 5;
} else if (highestMag >= 2.0) {
  priority = 4;
}

const primaryUrl = newEvents[0]?.url || USGS_MAP_URL;

const ntfyPayload = {
  topic: 'NJQuake',
  title,
  message: lines.join('\n').trim(),
  priority,
  tags: ['warning', 'earthquake', 'njquake'],
  markdown: true,
  click: primaryUrl,
  actions: [
    { action: 'view', label: 'USGS Details', url: primaryUrl, clear: false }
  ]
};

return [{ json: { shouldSend: true, newCount: newEvents.length, ntfyPayload } }];

function hashId(value) {
  let hash = 2166136261;
  value = String(value || '');
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

return $input.all().map((item) => {
  const j = item.json || {};
  const p = j.ntfyPayload || {};
  const title = String(p.title || 'Earthquake Alert').trim();
  const message = String(p.message || '').trim();
  const now = new Date().toISOString();
  const sourceEventId = hashId(title + '|' + message);

  const alert = {
    schema_version: '1.0',
    alert_id: `EARTHQUAKE:${sourceEventId}`,
    source: 'EARTHQUAKE',
    source_event_id: sourceEventId,
    category: 'OEM',
    subtype: 'EARTHQUAKE',
    status: 'ACTIVE',
    event_action: 'NEW',
    title,
    message: message || 'Regional seismic activity detected.',
    priority: Number(p.priority || 3),
    county: '',
    municipality: '',
    location: {
      label: 'Regional seismic event',
      address: '',
      state: '',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['earthquake', 'seismic', 'usgs'],
    click_url: String(p.click || ''),
    source_url: String(p.click || ''),
    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,
    metadata: {
      new_count: Number(j.newCount || 0),
      ntfy_topic: String(p.topic || 'NJQuake')
    }
  };

  alert.search_text = [
    alert.source, alert.category, alert.subtype,
    alert.title, alert.message, ...alert.tags
  ].filter(Boolean).join(' ');

  return { json: alert };
});
